/// Plain-`f64` tail of `ln(1+z)`: `(ln(1+z) − z)/z² = ∑ (−1)ᵏ⁺¹ zᵏ/(k+2)`,
/// low-degree first.  Degree 7 over the exact-`z` cells' range `|z| ≤ 2⁻⁷·⁴⁸`;
/// the truncation past `z⁷`, scaled by `z²`, is `z¹⁰/10 ≤ 2⁻⁷⁸` — far under
/// the fast leg's `2⁻⁶⁶` budget.
const LN1P_Q_COEFFS: [f64; 8] = [
    -0.5,
    0.3333333333333333,
    -0.25,
    0.2,
    -0.16666666666666666,
    0.14285714285714285,
    -0.125,
    0.1111111111111111,
];

/// Correction-scaled Ziv gate for `ln_1p`'s small-`|x|` branch (`|x| < 1/256`):
/// the absolute error bound is `x² · LN1P_SMALL_ZIV_SCALE`.
///
/// Every error in the branch scales with the `x²·Q(x)` correction: the Estrin
/// evaluation of [`LN1P_Q_COEFFS`] (≈4·2⁻⁵⁴ against `|Q| ≈ ½`), the roundings
/// of `x·x` and of the `x²·Q` product (≤2⁻⁵⁴ relative each), and the degree-7
/// truncation (`x⁷/10 ≤ 2⁻⁵⁹` relative to the correction) — together under
/// `2⁻⁵¹·⁴·x²`, so `2⁻⁴⁸` keeps a ~10× margin.  Scaling the gate by `x²` (the
/// old gate was a flat `2⁻⁵⁶` *relative*, sized for the worst `|x| ≈ 2⁻⁸`)
/// drops the straddle odds to `≈2⁻⁴⁵·|x|` — the fallback all but vanishes,
/// where the flat gate fell back on ≈2⁻³·⁵ of random small inputs.
const LN1P_SMALL_ZIV_SCALE: f64 = 3.552713678800501e-15; // 2^-48

/// Ziv gate for the natural log's fast path, as an absolute error bound.
///
/// The exact-`z` fast leg is good to <2⁻⁶⁶ absolute: the reduction commits no
/// error (`z` is exact, `e·LN2_HI + l1` is exact, the Fast2Sum with `z` is
/// exact), so the budget is the plain-`f64` tail — Estrin evaluation
/// ≈3·2⁻⁵⁴·z² ≤ 2⁻⁶⁷·⁴ at `|z| ≤ 2⁻⁷·⁴⁸`, plus ≈2⁻⁶⁹ each from rounding `z²`,
/// the `z²·Q` product, and the low-word folds, plus 2⁻⁷⁸ truncation and the
/// 2⁻⁹⁶/2⁻⁸⁸ table and `ln 2` splits.  `2⁻⁶³` keeps an 8× margin.  Being
/// absolute, the gate only forces the accurate fallback for `|ln x| ≲ 2⁻¹⁰`,
/// i.e. `x` within ~2⁻¹⁰ of 1.
const LN_ZIV_EPS: f64 = 1.0842021724855044e-19; // 2^-63

/// Ziv gate for `log2`/`log10`, scaled from [`LN_ZIV_EPS`] by `log2(e)` so it
/// bounds the absolute error of `ln_fast(x) · log_b(e)`.
const LOG2_ZIV_EPS: f64 = 1.5641377104174595e-19; // 2^-63 · log2(e), rounded up
const LOG10_ZIV_EPS: f64 = 1.0842021724855044e-19; // 2^-63 (≥ 2^-63 · log10(e))

const LOG2_E_HI: f64 = 1.4426950408889634;
const LOG2_E_LO: f64 = 2.0355273740931033e-17;
const LOG10_E_HI: f64 = 0.4342944819032518;
const LOG10_E_LO: f64 = 1.098319650216765e-17;

/// `ln(1 + r)` as a double-double for `|r| ≤ 1/256`, via `ln(1+r) = r · P(r)`.
#[inline]
fn ln_1p_kernel(r: DoubleDouble) -> DoubleDouble {
    let (high, low) = LN1P_P_COEFFS[LN1P_P_COEFFS.len() - 1];
    let mut p = DoubleDouble { high, low };

    for &(high, low) in LN1P_P_COEFFS[..LN1P_P_COEFFS.len() - 1].iter().rev() {
        p = p * r + DoubleDouble { high, low };
    }

    p * r
}

/// Correctly-rounded `ln(1 + x)` for an exact `|x| < 1/256`, anchored at the
/// result.
///
/// `ln(1+x) = x + x²·Q(x)` with `Q(x) = (ln(1+x) − x)/x² = ∑_{k≥0} (−1)ᵏ⁺¹ xᵏ/(k+2)`
/// — the [`LN1P_P_COEFFS`] series shifted down past its leading `1`.  Evaluating
/// only the correction `c = x²·Q(x)` as a double-double keeps its ≈2⁻¹⁰⁴ relative
/// error on the *tiny* `c` (≲2⁻⁹·|x|), so adding the **exact** `x` leaves an
/// absolute error far under ½ ulp of the result.  [`super::double::round_anchored`]
/// then breaks the hardest corpus ties (where `x + c.high` lands on a midpoint) by
/// the sign of the exact sticky tail `c.low`.
#[inline]
fn log1p_small_accurate(x: f64) -> f64 {
    let xd = DoubleDouble { high: x, low: 0.0 };

    // Q(x) as a double-double Horner over LN1P_P_COEFFS[1..] (the P-series minus
    // its leading 1), then c = x²·Q(x).
    let (high, low) = LN1P_P_COEFFS[LN1P_P_COEFFS.len() - 1];
    let mut q = DoubleDouble { high, low };
    for &(high, low) in LN1P_P_COEFFS[1..LN1P_P_COEFFS.len() - 1].iter().rev() {
        q = q * xd + DoubleDouble { high, low };
    }
    let c = (xd * xd) * q;

    // result = round(x + c) with `x` exact: the result-anchored finisher.
    super::double::round_anchored(x, c)
}

/// Decompose a finite positive `x` into `(e, cell, z)` for the exact-`z` fast
/// leg: `x = 2^e · m` with `m ∈ [1, 2)`, `cell` the 7-bit-indexed [`LnCell`],
/// and `z = cell.r · m − 1` computed **exactly** by one fused multiply-add (the
/// lattice argument on [`LnCell`]) — the whole reduction is a table load and an
/// FMA, with no double-double residual to carry.
#[inline]
fn ln_exact_reduce(x: f64) -> (i64, &'static LnCell, f64) {
    let (_, Magnitude::Normalized(magnitude)) = normalize(x) else {
        // Callers guarantee a finite positive x.
        unreachable!()
    };

    let e = (magnitude >> EXP_SHIFT) - 1023;
    let j = ((magnitude >> (EXP_SHIFT - 7)) & 127) as usize;
    let m = f64::from_bits((magnitude as u64 & 0x000F_FFFF_FFFF_FFFF) | 0x3FF0_0000_0000_0000);

    let cell = &LN_CELLS[j];
    (e, cell, crate::fma(cell.r, m, -1.0))
}

/// Assemble `ln(2^e·m) = e·ln2 + (l1 + l2) + ln(1+z)` from an
/// [`ln_exact_reduce`] result, as an **unnormalized** pair: `high` is the
/// correctly-rounded sum of the dominant terms and `low` (≲2⁻¹⁵) carries the
/// rest, good to <2⁻⁶⁶ absolute (see [`LN_ZIV_EPS`]).  The in-file Ziv gates
/// consume this form directly; [`ln_fast`] renormalizes it for outside callers.
///
/// The serial chain is three steps: `e·LN2_HI + l1` is **exact** (both are
/// integer multiples of 2⁻⁴² and `|e·LN2_HI + l1| < 746`, i.e. fewer than 2⁵³
/// multiples), the Fast2Sum with the exact `z` is valid (the generator verifies
/// `|e·LN2_HI + l1|` is zero or ≥ max |z| for every reachable pair — the tight
/// cases `e = 0` and `e = −1` per cell), and the plain-`f64` tail of `ln(1+z)`
/// joins the low word off that path.
#[inline]
fn ln_exact_assemble(e: f64, cell: &LnCell, z: f64) -> DoubleDouble {
    // ln(1+z) − z = z²·Q(z), all plain f64: z is exact, so no residual threads
    // through the polynomial.
    let tail = (z * z) * crate::poly(z, &LN1P_Q_COEFFS);

    let s = fast_sum(crate::fma(e, LN2_HI, cell.l1), z);
    let low = tail + (s.low + cell.l2);
    DoubleDouble {
        high: s.high,
        low: crate::fast_mul_add(e, LN2_LO, low),
    }
}

/// Decompose a finite positive `x` into `(e, i, m·inv − 1)` for the log family.
///
/// `x = 2^e · m` with `m ∈ [1, 2)`; `i` is the 7-bit table index and the returned
/// double-double is `r = m · INV_TABLE[i] − 1 ∈ [−1/256, 1/256]`.
#[inline]
fn log_reduce(x: f64) -> (i64, usize, DoubleDouble) {
    let (_, Magnitude::Normalized(magnitude)) = normalize(x) else {
        // Callers guarantee a finite positive x.
        unreachable!()
    };

    let e = (magnitude >> EXP_SHIFT) - 1023;
    let i = ((magnitude >> (EXP_SHIFT - 7)) & 127) as usize;
    let m = f64::from_bits((magnitude as u64 & 0x000F_FFFF_FFFF_FFFF) | 0x3FF0_0000_0000_0000);

    // r = m·inv − 1 as a double-double.  `m·inv ∈ [≈0.996, 1.004]`, so the high
    // word minus one is exact (Sterbenz).
    let mi = DoubleDouble::from_product(m, INV_TABLE[i]);
    let r = fast_sum(mi.high - 1.0, mi.low);

    (e, i, r)
}

/// The natural logarithm of a finite positive `x ≠ 1`, as a double-double.
#[inline]
pub fn ln_dd(x: f64) -> DoubleDouble {
    // ln(x) = e·ln2 + L_TABLE[i] + ln(1+r).
    let (e, i, r) = log_reduce(x);
    let e = e as f64;

    let e_ln2 = DoubleDouble {
        high: e * LN2_HI,
        low: e * LN2_LO,
    };
    let (high, low) = L_TABLE[i];
    e_ln2 + DoubleDouble { high, low } + ln_1p_kernel(r)
}

/// The exact-`z` fast leg end to end, returning the raw unnormalized pair of
/// [`ln_exact_assemble`] — the form the in-file Ziv gates consume.
#[inline]
fn ln_fast_raw(x: f64) -> DoubleDouble {
    let (e, cell, z) = ln_exact_reduce(x);
    ln_exact_assemble(e as f64, cell, z)
}

/// Lean natural logarithm of a finite positive `x ≠ 1`, as a double-double.
///
/// The exact-`z` fast leg ([`ln_exact_reduce`] + [`ln_exact_assemble`]), good to
/// <2⁻⁶⁶ absolute — see [`LN_ZIV_EPS`].  The closing Fast2Sum renormalizes the
/// pair for the outside consumers (`pow`, the inverse hyperbolics, `lgamma`);
/// its ordering can only fail when the result nearly cancels (`x` within ~2⁻⁸
/// of 1), where `high` still rounds correctly and every caller's absolute Ziv
/// gate rejects the result regardless.  The callers gate this against an
/// accurate fallback ([`dint::ln_accurate`] for `ln`, [`ln_dd`] for the rest).
#[inline]
pub fn ln_fast(x: f64) -> DoubleDouble {
    let DoubleDouble { high, low } = ln_fast_raw(x);
    fast_sum(high, low)
}

/// Lean natural logarithm of `2^k · x`, as a double-double — [`ln_fast`] with the
/// binary exponent biased by `k`.
///
/// `ln(2^k·x) = (e+k)·ln2 + (l1 + l2) + ln(1+z)`, so the scale folds into the
/// reduction's exponent for free, avoiding a separate `+ k·ln2` double-double add.
/// `(e+k)·LN2_HI` stays exact for `|e+k| ≤ 1074`.  Used by the inverse-hyperbolic
/// large-|x| path (`ln(2|x|)`, `k = 1`).
#[inline]
pub fn ln_fast_scaled(x: f64, k: i64) -> DoubleDouble {
    let (e, cell, z) = ln_exact_reduce(x);
    let DoubleDouble { high, low } = ln_exact_assemble((e + k) as f64, cell, z);
    fast_sum(high, low)
}

/// Lean `ln(s)` for a finite double-double `s > 1`, as a raw unnormalized pair
/// (the form the in-file Ziv gates consume — see [`ln_exact_assemble`]).
///
/// `ln(s.high + s.low) = ln(s.high) + ln(1 + s.low/s.high)`.  Rather than form
/// the linear correction `s.low/s.high` with a hardware division, fold `s.low`
/// straight into the exact-`z` reduction the way [`log1p`] folds its tail: with
/// `δ = s.low·2⁻ᵉ` the true mantissa is `m + δ`, so the reduced argument gains
/// `cell.r·δ`, whose image through `ln` is `cell.r·δ·(1 − z)` up to a dropped
/// `cell.r·δ·z² ≲ 2⁻⁶⁷` — inside the inverse-hyperbolic gate.  The inverse-
/// hyperbolic callers (`atanh`, and `asinh`/`acosh` via `ln_sqrt_rounded`) all
/// pass `s > 1`, so `e ≥ 0` and `2⁻ᵉ` never overflows.
#[inline]
pub fn ln_dd_fast(s: DoubleDouble) -> DoubleDouble {
    let (e, cell, z) = ln_exact_reduce(s.high);
    let delta = s.low * crate::exp2i(-e);
    let dz = cell.r * delta;
    let dz = crate::fast_mul_add(-dz, z, dz);
    let DoubleDouble { high, low } = ln_exact_assemble(e as f64, cell, z);
    DoubleDouble {
        high,
        low: low + dz,
    }
}

/// The natural logarithm
#[must_use]
#[inline]
pub fn log(x: f64) -> f64 {
    if x.is_nan() {
        return x;
    }
    if x < 0.0 {
        return f64::NAN;
    }
    if x == 0.0 {
        return f64::NEG_INFINITY;
    }
    if x == 1.0 || x == f64::INFINITY {
        return x - 1.0;
    }

    // Two-step Ziv method.  The lean fast path is correctly rounded unless the
    // true value lies within `LN_ZIV_EPS` of a rounding boundary, in which case
    // the always-correct 128-bit accurate path resolves it.  The raw pair feeds
    // the gate directly — `high + (low ± eps)` needs no renormalization.
    let DoubleDouble { high, low } = ln_fast_raw(x);
    let left = high + (low - LN_ZIV_EPS);
    let right = high + (low + LN_ZIV_EPS);
    if left == right {
        left
    } else {
        super::dint::ln_accurate(x)
    }
}

/// The base-2 logarithm
#[must_use]
#[inline]
pub fn log2(x: f64) -> f64 {
    if x.is_nan() {
        return x;
    }
    if x < 0.0 {
        return f64::NAN;
    }
    if x == 0.0 {
        return f64::NEG_INFINITY;
    }
    if x == 1.0 || x == f64::INFINITY {
        return x - 1.0;
    }

    // log2(x) = ln(x) · log2(e).  Fast path: lean ln × log2(e), accepted when the
    // Ziv interval does not straddle a rounding boundary; otherwise the
    // double-double ln resolves it.  The raw pair multiplies fine unnormalized:
    // the dropped `low·LOG2_E_LO` is ≤ 2⁻¹⁵·2⁻⁵⁵ and the cross-term fold rounds
    // at ≲2⁻⁶⁷·⁵, both inside the gate's margin.
    let log2e = DoubleDouble {
        high: LOG2_E_HI,
        low: LOG2_E_LO,
    };
    let DoubleDouble { high, low } = ln_fast_raw(x) * log2e;
    let left = high + (low - LOG2_ZIV_EPS);
    let right = high + (low + LOG2_ZIV_EPS);
    if left == right {
        return left;
    }

    super::dint::log2_accurate(x)
}

/// The base-10 logarithm
#[must_use]
#[inline]
pub fn log10(x: f64) -> f64 {
    if x.is_nan() {
        return x;
    }
    if x < 0.0 {
        return f64::NAN;
    }
    if x == 0.0 {
        return f64::NEG_INFINITY;
    }
    if x == 1.0 || x == f64::INFINITY {
        return x - 1.0;
    }

    // log10(x) = ln(x) · log10(e).  Fast path with a Ziv test, as in `log2`.
    let log10e = DoubleDouble {
        high: LOG10_E_HI,
        low: LOG10_E_LO,
    };
    let DoubleDouble { high, low } = ln_fast_raw(x) * log10e;
    let left = high + (low - LOG10_ZIV_EPS);
    let right = high + (low + LOG10_ZIV_EPS);
    if left == right {
        return left;
    }

    super::dint::log10_accurate(x)
}

/// Compute `ln(1 + x)` accurately, especially for small `x`
#[must_use]
#[inline]
pub fn log1p(x: f64) -> f64 {
    if x.is_nan() || x == 0.0 {
        // Preserve the sign of zero: ln_1p(±0) = ±0.
        return x;
    }
    if x < -1.0 {
        return f64::NAN;
    }
    if x == -1.0 {
        return f64::NEG_INFINITY;
    }
    if x == f64::INFINITY {
        return x;
    }

    // |x| < 2⁻⁵⁴: ln(1+x) = x − x²/2 + … rounds to x itself — even for a
    // power-of-two x the correction `x²/2 < 2⁻¹⁰⁹` sits under a quarter of the
    // downward ulp `2⁻¹⁰⁷` — and computing `x²` here would underflow into a
    // subnormal (a microcode assist on the representation-uniform bench's
    // dominant tiny-|x| draws).  Return x directly.
    if x.abs() < 5.551115123125783e-17 {
        return x;
    }

    // Small |x|: evaluate ln(1+x) = x·P(x) directly.  This avoids the table's
    // `L[i] + ln(1+r)` cancellation, which would cap accuracy when the result is
    // tiny, and `x` is already an exact reduced argument in the kernel's range.
    if x.abs() < 1.0 / 256.0 {
        // Fast path: `x` is exact here, so `ln(1+x) = x + x²·Q(x)` evaluates
        // directly with the shared degree-7 plain-`f64` `Q`, and the `x` lead
        // stays exact in the Fast2Sum.  The Ziv gate scales with the `x²`
        // correction ([`LN1P_SMALL_ZIV_SCALE`]) — every error source does — so
        // the straddle odds shrink with `|x|` and the accurate kernel almost
        // never runs.  When `x²` underflows the gate is 0 and `x` itself is the
        // correctly rounded result (the dropped `−x²/2` is far below ½ ulp).
        let zz = x * x;
        let tail = zz * crate::poly(x, &LN1P_Q_COEFFS);
        let DoubleDouble { high, low } = fast_sum(x, tail);
        let err = LN1P_SMALL_ZIV_SCALE * zz;
        let lo = high + (low - err);
        let hi = high + (low + err);
        if lo == hi {
            return lo;
        }

        // Accurate fallback, anchored at the *result*: the `dint` path forms a
        // 128-bit `1 + x` whose window sits at magnitude `1`, leaving only ≈86
        // bits at a tiny result like `x ≈ 2⁻⁴²` — short of the near-½-ulp ties
        // here.  Instead compute only the correction `c = ln(1+x) − x = x²·Q(x)`
        // as a double-double: its ≈2⁻¹⁰⁴ relative error rides the *tiny* `c`, not
        // the result, so `x` (exact) + `c` resolves the rounding.
        return log1p_small_accurate(x);
    }

    // Otherwise carry 1 + x exactly as `s + c` (Fast2Sum), so the bits of `x` lost
    // in forming `s` are kept in `c`.  `1 + x` is commutative, so the high word is
    // the same either way; only the residual depends on which operand is larger.
    let s = 1.0 + x;
    let c = if x.abs() <= 1.0 {
        x - (s - 1.0)
    } else {
        1.0 - (s - x)
    };

    // Fast leg: reduce s = 2^e·m with the exact-`z` cells as for `ln`, then fold
    // the tail `c` into the low word: with δ = c·2⁻ᵉ the true mantissa is m + δ,
    // so the true reduced argument is z + r·δ.  `|δ| ≤ ½ulp(m)` makes
    // `dz = r·δ ≤ 2⁻⁵³`, and its first-order image through ln, `dz/(1+z)`, is
    // `dz·(1 − z)` up to a dropped `dz·z² ≤ 2⁻⁶⁸` — inside the gate's margin.
    let (e, cell, z) = ln_exact_reduce(s);
    let delta = if e > -1000 { c * crate::exp2i(-e) } else { 0.0 };
    let dz = cell.r * delta;
    let dz = crate::fast_mul_add(-dz, z, dz);

    // `|x| ≥ 1/256` keeps `|ln(1+x)| ≥ ln(255/256) ≈ 2⁻⁸` away from zero, so the
    // same absolute gate as `ln` applies; fall back to the accurate kernel on a
    // straddle.
    let DoubleDouble { high: rh, low: rl } = ln_exact_assemble(e as f64, cell, z);
    let rl = rl + dz;
    let lo = rh + (rl - LN_ZIV_EPS);
    let hi = rh + (rl + LN_ZIV_EPS);
    if lo == hi {
        return lo;
    }

    // Accurate fallback: `1 + x = s + c` exactly, so feed that exact sum to the
    // correctly-rounded 128-bit `dint` log (the same path `ln`/`log2`/`log10`
    // use).  This resolves the hard-to-round cases the double-double kernel mis-rounds.
    super::dint::log1p_accurate(s, c)
}
